"""Generate native clerk data from pinned upstream modules; Python -I -B."""

from pathlib import Path
import json
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "tools/clerks_test"))
from upstream import (
    PetDNA,
    PetTraits,
    PetConstants,
    PetNameGenerator,
    KartDNA,
    FishTank,
)


def quoted(value):
    return json.dumps(value, ensure_ascii=True)


def main():
    names = PetNameGenerator.PetNameGenerator().nameDictionary
    lines = [
        "// GENERATED by tools/gen_clerk_tables.py from pinned upstream. Do not edit.",
        "#pragma once",
        "#include <cstdint>",
        "namespace tt::clerks {",
        "struct PetName {\n    uint8_t gender;\n    const char* name;\n};",
        "inline constexpr PetName kPetNameRows[] = {",
    ]
    assert max(names) == 2712
    for index in range(2713):
        gender, name = names.get(index, names[0])
        lines.append("    {%d, %s}," % (gender, quoted(name)))
    lines.append("};")
    for label, gender in [("Boy", 0), ("Girl", 1)]:
        ids = [index for index, value in names.items() if value[0] == 2]
        ids += [index for index, value in names.items() if value[0] == gender]
        ids = [
            next(key for key, value in names.items() if value[1] == names[index][1])
            for index in ids
        ]
        lines.append("inline constexpr uint16_t k%sNames[] = {" % label)
        for start in range(0, len(ids), 16):
            lines.append("    " + ", ".join(map(str, ids[start : start + 16])) + ",")
        lines.append("};")
    lines.append("inline constexpr float kPetColors[26][4] = {")
    for color in PetDNA.AllPetColors:
        lines.append(
            "    {"
            + ",".join(
                format(float(v), ".9g") + "f" if float(v) % 1 else str(int(v)) + ".0f"
                for v in color
            )
            + "},"
        )
    lines.append("};")
    lines.append(
        "inline constexpr double kBodyRarity[] = {"
        + ",".join(repr(PetDNA.getBodyRarity(i)) for i in range(7))
        + "};"
    )
    lines.append(
        "inline constexpr const char* kBodyNames[] = {"
        + ",".join(map(quoted, PetDNA.BodyTypes))
        + "};"
    )
    lines.append(
        "struct HoodPets {\n    uint32_t zone;\n    int low;\n    int high;\n    uint8_t bodies[7];\n    uint8_t weights[7];\n    int count;\n};"
    )
    lines.append("inline constexpr HoodPets kHoodPets[] = {")
    for zone, weights in PetDNA.PetRarities["body"].items():
        bodies = [PetDNA.BodyTypes.index(name) for name in weights]
        lines.append(
            "    {%d,%d,%d,{%s},{%s},%d},"
            % (
                zone,
                *PetConstants.ZoneToCostRange[zone],
                ",".join(map(str, bodies)),
                ",".join(map(str, weights.values())),
                len(weights),
            )
        )
    lines += [
        "};",
        "struct KartItem {\n    const char* name;\n    int cost;\n    int type;\n    float color[4];\n};",
        "inline constexpr KartItem kKartBodies[] = {",
    ]
    for item in KartDNA.KartDict.values():
        lines.append("    {%s,%d,0,{1,1,1,1}}," % (quoted(item[0]), item[2]))
    lines += ["};", "inline constexpr KartItem kKartAccessories[] = {"]
    for index, item in KartDNA.AccessoryDict.items():
        color = item[1] if index >= 65 else (1, 1, 1, 1)
        lines.append(
            "    {%s,%d,%d,{%s}},"
            % (
                quoted(item[0]),
                item[2],
                int(KartDNA.getAccessoryType(index)),
                ",".join(
                    format(float(v), ".9g") + "f"
                    if float(v) % 1
                    else str(int(v)) + ".0f"
                    for v in color
                ),
            )
        )
    lines += [
        "};",
        "struct FishRarity {\n    int genus;\n    int species;\n    int rarity;\n};",
        "inline constexpr FishRarity kFishRarities[] = {",
    ]
    from toontown.fishing import FishGlobals

    for genus, species_map in FishGlobals.__fishDict.items():
        for species in range(len(species_map)):
            lines.append(
                "    {%d,%d,%d},"
                % (genus, species, FishGlobals.getRarity(genus, species))
            )
    lines += ["};", "} // namespace tt::clerks", ""]
    (ROOT / "source/ui/clerk_tables.h").write_text("\n".join(lines))
    print("Clerk tables: 2713 names, 6 hoods, 3 kart bodies, 92 accessories")


if __name__ == "__main__":
    main()
